engine.analyze:
async function analyze(input, providers) {
  // ── Local helpers (closure-scoped to satisfy the bundler) ────────────
  function _validateErrorData(data) {
    if (!Array.isArray(data)) return [];
    return data.filter(function (item) {
      return item && item.original && item.correction;
    });
  }
  // Footer text cleanup → kernel `eli.host.cleanText` (apiVersion 2).
  // Strips Word comment nodes / del-spans / page numbers / [abc12]
  // markers via DOMParser. Same algorithm v2 used in
  // getCleanTextAndContext (taskpane_v2.js:13021).
  function _normalizeWhitespace(text) {
    if (!text) return "";
    return String(text).replace(/\s+/g, " ").trim();
  }
  function _buildResult(items, warnings, totalWords, settings, input, overview) {
    // Read build timestamp from the bundle record the kernel stamped.
    // releasedAt is an ISO string set by build_tool.js on every publish —
    // it's the canonical version identifier (replaces hand-bumped __version).
    var toolVer = "unknown";
    try {
      if (typeof window !== "undefined" && window.eli && window.eli.tools && window.eli.tools._loaded
          && window.eli.tools._loaded["error_review"]) {
        toolVer = window.eli.tools._loaded["error_review"].releasedAt || "unknown";
      }
    } catch (e) { /* tolerate */ }
    return {
      items: items,
      warnings: warnings,
      totalWords: totalWords,
      overview: overview,
      provenance: {
        kernelVersion: (typeof window !== "undefined" && window.eli)
          ? window.eli.kernelVersion : "node",
        toolVersion: toolVer,
        promptVersion: "errorCheck@v16",
        model: (typeof window !== "undefined" && window.eli && window.eli.ai &&
                typeof window.eli.ai.getModel === "function")
          ? window.eli.ai.getModel() : null,
        timestamp: Date.now(),
        docHash: input && input.docHash || null,
        settings: settings,
      },
    };
  }

  var settings = (input && input.settings) || {};
  var onLog = (input && typeof input.onLog === "function") ? input.onLog : function () { };
  var sensitivity = settings.sensitivity || "Balanced";
  var scope = settings.scope === "selection" ? "selection" : "full";
  // 2026-05-16: both scopes use shared ELI_IDX_* via
  // eli.host.helpers.getPromptAnchors. Full scope is a straight call.
  // Selection scope writes ELI_IDX_* on the WHOLE body (so LOCATE on
  // any cited paragraph works), then filters the result to only the
  // paragraphs whose Range overlaps the user's selection — body
  // indices preserved in the ids so highlightAnchor jumps correctly.
  onLog({ kind: "step", id: "extract", icon: "⏳",
    text: scope === "selection" ? "Extracting selected paragraphs..." : "Extracting paragraphs..." });

  if (!providers.host || !providers.host.helpers || typeof providers.host.helpers.getPromptAnchors !== "function") {
    throw new Error("eli.host.helpers.getPromptAnchors unavailable — kernel too old");
  }

  var allAnchors = await providers.host.helpers.getPromptAnchors({ minLen: 6 });
  var extracted;
  if (scope === "selection") {
    // Resolve which body paragraph indices fall inside the selection,
    // then filter allAnchors to that subset. compareLocationWith returns
    // "Equal" | "ContainedBy" | "Contains" | "Overlaps" | "InsideStart" |
    // "InsideEnd" | "AdjacentBefore" | "AdjacentAfter" | "Before" | "After".
    // We treat "Equal", "ContainedBy", "InsideStart", "InsideEnd" as in-range.
    var inRangeSet = await providers.host.runRaw("error_review:extract_selection_indices", function (context) {
      var selectionRange = context.document.getSelection();
      var paragraphs = context.document.body.paragraphs;
      paragraphs.load("items");
      return context.sync().then(function () {
        var n = paragraphs.items.length;
        var comparisons = [];
        for (var i = 0; i < n; i++) {
          comparisons.push(paragraphs.items[i].getRange().compareLocationWith(selectionRange));
        }
        return context.sync().then(function () {
          var hits = {};
          for (var j = 0; j < n; j++) {
            var v = comparisons[j].value;
            if (v === "Equal" || v === "ContainedBy" || v === "InsideStart" || v === "InsideEnd") {
              hits[j] = true;
            }
          }
          return hits;
        });
      });
    });
    var filtered = allAnchors.filter(function (a) {
      var m = String(a.id || "").match(/(\d+)$/);
      if (!m) return false;
      return !!inRangeSet[parseInt(m[1], 10)];
    });
    var fullText = "";
    filtered.forEach(function (a) { fullText += (a.text || "") + "\n"; });
    extracted = {
      payloadJSON: JSON.stringify(filtered),
      paragraphCount: filtered.length,
      fullText: fullText,
    };
  } else {
    var fullText2 = "";
    allAnchors.forEach(function (a) { fullText2 += (a.text || "") + "\n"; });
    extracted = {
      payloadJSON: JSON.stringify(allAnchors),
      paragraphCount: allAnchors.length,
      fullText: fullText2,
    };
  }

  if (extracted.paragraphCount === 0) {
    onLog({ kind: "step", id: "extract", icon: "⚠️", text: "No paragraphs to scan.", warn: true });
    return _buildResult([], [], 0, settings, input, "Document is empty.");
  }

  onLog({
    kind: "step", id: "extract", icon: "📑",
    text: "Extracted " + extracted.paragraphCount + " paragraph(s)",
  });

  // ── Step 1a: Resolve tracked changes per paragraph (2026-05-16). ─────
  // Without this step, paragraph.text returns insertion + struck-through
  // deletion text jammed together when the doc has pending tracked
  // changes. AI sees garbled strings like "the cust customer omer shall"
  // and flags them as errors — bizarre fix suggestions are the symptom.
  // Common trigger: user runs scan once, applies some fixes (which land
  // as tracked changes), then re-runs the scan in the same session.
  //
  // Fix: per paragraph with pending tracked changes, substitute the
  // POST-ACCEPT text (insertions kept, deletions removed) so the AI
  // sees what the final clause will read as. Uses the kernel helper
  // shipped with host apiVersion 3. Silent no-op when the helper or
  // tracked changes are absent (clean doc / older kernel).
  if (providers.host.helpers &&
      typeof providers.host.helpers.readResolvedText === "function") {
    try {
      var resolvedByIdx = await providers.host.runRaw("error_review:resolve_redlines", async function (ctx) {
        var paras = ctx.document.body.paragraphs;
        paras.load("items");
        await ctx.sync();
        // Phase-1 triage: cheap getTrackedChanges per paragraph, all
        // batched into one sync.
        var probes = [];
        for (var pi = 0; pi < paras.items.length; pi++) {
          var p = paras.items[pi];
          var c = p.getTrackedChanges();
          c.load("items");
          probes.push({ paraIdx: pi, para: p, changesReq: c });
        }
        await ctx.sync();
        var hits = probes.filter(function (pr) {
          return pr.changesReq.items && pr.changesReq.items.length > 0;
        });
        if (!hits.length) return {};
        // Phase 2: resolved text per hit paragraph (parallel reads in
        // one sync via readResolvedText's batched OOXML+text load).
        var resolvedPromises = hits.map(function (pr) {
          return providers.host.helpers.readResolvedText(pr.para).then(function (info) {
            return { idx: pr.paraIdx, info: info };
          });
        });
        var results = await Promise.all(resolvedPromises);
        var out = {};
        results.forEach(function (r) {
          if (r && r.info && r.info.hasRedlines && r.info.resolvedText) {
            out[r.idx] = r.info.resolvedText;
          }
        });
        return out;
      });
      // Substitute resolved text into the anchor payload.
      var replaceCount = 0;
      var replaceAnchorsArray = function (arr) {
        for (var i = 0; i < arr.length; i++) {
          var a = arr[i];
          var m = String(a.id || "").match(/_(\d+)$/);
          if (!m) continue;
          var idx = parseInt(m[1], 10);
          if (resolvedByIdx[idx] && resolvedByIdx[idx] !== a.text) {
            arr[i] = { id: a.id, text: resolvedByIdx[idx] };
            replaceCount++;
          }
        }
      };
      // Parse the payloadJSON, substitute, re-serialize. Same JSON
      // shape goes downstream regardless.
      try {
        var parsedAnchors = JSON.parse(extracted.payloadJSON || "[]");
        if (Array.isArray(parsedAnchors)) {
          replaceAnchorsArray(parsedAnchors);
          extracted.payloadJSON = JSON.stringify(parsedAnchors);
          var newFull = "";
          parsedAnchors.forEach(function (a) { newFull += (a.text || "") + "\n"; });
          extracted.fullText = newFull;
        }
      } catch (_) { /* tolerate JSON edge cases */ }
      if (replaceCount > 0) {
        onLog({
          kind: "step", id: "redline_resolve", icon: "✓",
          text: "Resolved redlines in " + replaceCount + " paragraph(s) (using post-accept text for AI)",
        });
      }
    } catch (e) {
      // Tolerate — fall through to original text. Scan still works, just
      // with the original "garbled redlined" content.
      onLog({
        kind: "step", id: "redline_resolve", icon: "⚠️",
        text: "Could not resolve redlines; AI may see noisy text in redlined paragraphs.",
        warn: true,
      });
    }
  }

  // ── Step 1b: Build structural map (kernel apiVersion 2 — additive). ────
  // Returns a hierarchy of sections (Article/Section/numbered/uppercase
  // headers detected via Word list metadata + regex + outlineLevel) and
  // tags every body paragraph with `belongsTo: "<enclosing header>"`.
  // We use it for two things:
  //   1. Each error card gets a section badge ("§ 4.5 · Confidentiality")
  //      so the reviewer sees the context without leaving the report.
  //   2. The AI prompt embeds a SECTIONS IN THIS DOCUMENT block, and
  //      Step 1c tags every payload entry with a `section` field. Together
  //      these enable (a) cross-reference validation ("Section 4.5 cited
  //      but doc only has 4.4 and 5.4 — likely typo") and (b) self-
  //      reference validation ("this Section 5" inside Section 3).
  //
  // Kernel caches the map by docHash + invalidates on doc:dirty, so
  // repeated runs in the same session are ~0ms. Failure here is non-fatal
  // — the engine still emits the standard error report without section
  // context.
  var structuralMap = null;
  try {
    if (providers.host && typeof providers.host.readStructuralMap === "function") {
      onLog({ kind: "step", id: "structural", icon: "⏳", text: "Indexing sections..." });
      structuralMap = await providers.host.readStructuralMap({ prefix: "ELI_IDX_" });
      onLog({
        kind: "step", id: "structural", icon: "🗂",
        text: "Indexed " + (structuralMap.headerCount || 0) + " section header(s)",
      });
    }
  } catch (e) {
    onLog({ kind: "step", id: "structural", icon: "⚠️", text: "Section indexing failed: " + (e && e.message), warn: true });
    structuralMap = null;
  }

  // ── Step 1c: Enrich the AI payload with each paragraph's section ──────
  // The AI gets [{id, text}] today. To catch SELF-reference errors —
  // text inside Section 3 that says "this Section 5" — the AI must know
  // which section each paragraph physically sits in. Cross-ref alone
  // can't catch it: "Section 5" exists elsewhere, so the number-lookup
  // passes. We tag every payload entry with `section` (the enclosing
  // header's number + title) so the AI can compare cited vs. enclosing.
  // Only for "full" scope — in "selection" scope payload ids index into
  // the selection, not the body, so getSection(idx) would mis-map.
  // _cleanSectionNumber — the kernel stores the raw header match, which
  // carries the leading "Section/Article" word AND a trailing period
  // ("Section 12.", "Article 12."). Strip both so we keep just the
  // numeric token ("12.4", "12") — otherwise the AI reads "Section 12"
  // and never sees the ".4".
  function _cleanSectionNumber(n) {
    return String(n || "")
      .replace(/^(?:article|section|clause|exhibit|appendix)\s+/i, "")
      .replace(/[.\s]+$/, "")
      .trim();
  }
  var payloadForAI = extracted.payloadJSON;
  if (structuralMap && structuralMap.headerCount > 0 && scope === "full") {
    try {
      var _parsed = JSON.parse(extracted.payloadJSON);
      _parsed.forEach(function (entry) {
        var pm = entry && entry.id && entry.id.match(/_(\d+)$/);
        if (!pm) return;
        var pIdx = parseInt(pm[1], 10);
        if (!isFinite(pIdx)) return;
        var sec = structuralMap.getSection(pIdx);
        var num = sec ? _cleanSectionNumber(sec.number !== "[Unnumbered]" ? sec.number : "") : "";
        var title = (sec && sec.title) ? String(sec.title).trim() : "";
        // getSection's backward walk lands on the PARENT ("Section 12")
        // when a sub-section header ("12.4") isn't detected as
        // structural. The paragraph's own leading number is the most
        // authoritative section identity — prefer it when it's deeper
        // (more dot-segments) than what getSection returned.
        var ownNum = String(entry.text || "").match(/^\s*(?:Section\s+)?(\d+(?:\.\d+)+)\b/i);
        if (ownNum && ownNum[1].split(".").length > String(num).split(".").length) {
          num = ownNum[1];
        }
        if (num || title) {
          entry.section = num ? (num + (title ? " " + title : "")) : title;
        }
      });
      payloadForAI = JSON.stringify(_parsed);
    } catch (e) { payloadForAI = extracted.payloadJSON; }
  }

  // ── Step 2: Footer consistency check (CP Ref / A-NNN matching) ───────
  // Walks every Primary/FirstPage/EvenPages footer across all sections,
  // pulls a CP Ref or A-NNN from page-1, then flags mismatched ones.
  // Mirrors v2's checkFooterConsistency. Independent of AI; runs in
  // parallel with the AI scan below.
  onLog({ kind: "step", id: "footer", icon: "⏳", text: "Checking footer consistency..." });
  // Id prefix downstream code matches against (init.js: id.indexOf("footer_"),
  // /footer_(\d+)_([A-Za-z]+)/, id.indexOf("_footer_"), id.indexOf("_err")).
  // 2026-05-17: declaration was missing — `prefix` was referenced below in
  // the id template literal but never defined, throwing "prefix is not
  // defined" the moment the footer-check ran (= every Error Review click).
  var prefix = "ELI_ER_";
  var footerErrorsPromise = providers.host.runRaw("error_review:footers", function (context) {
    var sections = context.document.sections;
    sections.load("items");
    return context.sync().then(function () {
      var footerRanges = [];
      sections.items.forEach(function (section, index) {
        ["Primary", "FirstPage", "EvenPages"].forEach(function (type) {
          try {
            var f = section.getFooter ? section.getFooter(type) : section.footers.getItem(type);
            var r = f.getRange();
            var h = r.getHtml();
            footerRanges.push({ type: type, section: index + 1, html: h });
          } catch (e) { /* type not present in this section */ }
        });
      });
      return context.sync().then(function () {
        var errors = [];
        var refRegex = /(CP Ref:|A-)\s*([A-Za-z0-9\-]+)/i;
        function getText(item) {
          if (!item || !item.html) return "";
          return providers.host.helpers.cleanText(item.html.value || "");
        }
        var p1First = footerRanges.find(function (r) {
          return r.section === 1 && r.type === "FirstPage" && getText(r).trim().length > 0;
        });
        var p1Prim = footerRanges.find(function (r) {
          return r.section === 1 && r.type === "Primary" && getText(r).trim().length > 0;
        });
        var masterText = p1First ? getText(p1First) : (p1Prim ? getText(p1Prim) : "");
        var masterMatch = masterText.match(refRegex);
        if (!masterMatch) return [];
        var masterRef = masterMatch[0].trim();
        footerRanges.forEach(function (item) {
          var text = getText(item);
          if (text && text.trim().length > 0) {
            var match = text.match(refRegex);
            if (match) {
              var found = match[0].trim();
              if (found !== masterRef) {
                errors.push({
                  id: prefix + "footer_" + item.section + "_" + item.type,
                  original: found,
                  correction: masterRef,
                  reason: "Footer Mismatch: Section " + item.section + " (" + item.type +
                    ") has '" + found + "', but Page 1 is '" + masterRef + "'.",
                  error_type: "Consistency",
                  source: "footer",
                });
              }
            }
          }
        });
        return errors;
      });
    });
  }).catch(function (e) {
    return [{
      id: prefix + "footer_err",
      original: "Script Error",
      correction: "Footer Check",
      reason: "Footer-check logic error: " + (e && e.message || "unknown"),
      error_type: "System",
      source: "footer",
    }];
  });

  // ── Step 3: AI scan ──────────────────────────────────────────────────
  onLog({ kind: "step", id: "ai", icon: "⏳", text: "Sending to AI (sensitivity: " + sensitivity + ")..." });
  var aiErrorsPromise = (async function () {
    var promptRow = await providers.storage.get("prompts", "errorCheck");
    if (!promptRow || !promptRow.text) {
      throw new Error("Prompt template 'errorCheck' not in storage. Re-sync data bundles.");
    }

    // Build sensitivity-driven instructions block (v2 line 6280-6291).
    var instructions =
      "TASK 1: GRAMMAR, SPELLING & PUNCTUATION\n" +
      "Identify ALL grammatical errors, spelling mistakes, punctuation issues, " +
      "and awkward phrasing.\n" +
      "MISSING PUNCTUATION IS A TOP PRIORITY. Flag every instance of missing " +
      "punctuation including: missing periods at the end of sentences or " +
      "clauses, missing commas in addresses (city, state), lists, after " +
      "introductory clauses, and around appositives, missing semicolons " +
      "between independent clauses, and missing colons before lists.\n" +
      "Scan every sentence boundary. If a sentence or clause ends without a " +
      "period, question mark, or other required terminal punctuation, flag it.\n" +
      "DUPLICATE PUNCTUATION: Also flag duplicate or extra terminal punctuation " +
      "(e.g. \"end..\", \"end..\", \"sentence . .\"). The fix should ALWAYS retain " +
      "exactly ONE terminal period — never delete the final period when " +
      "removing extras. Same rule for repeated commas, question marks, and " +
      "exclamation marks.\n";
    if (sensitivity === "Picky") {
      instructions += "\nTASK 3: DEFINITION X-RAY\nScan for Capitalized words " +
        "not defined in the text.\n";
    }
    instructions += "\nIMPORTANT: Enforce US spelling. Flag UK spellings.\n";

    // 2026-05-13: cross-reference detection re-enabled now that the
    // engine builds a structural map of section headers and feeds the
    // AI a ground-truth SECTIONS list. The AI no longer has to guess
    // whether "Section 4.5" exists — it looks it up in the list.
    //
    // 2026-05-13 follow-up fix: previously this branch ALSO emitted a
    // "DISABLED" suppression block when the structural map was missing
    // — which was a regression vs v2. v2 also passed a sectionIndexBlock
    // substitution but the prompt template had no `{{sectionIndexBlock}}`
    // placeholder, so it silently dropped on the floor. The AI was
    // never told to suppress cross-ref; it just used its own judgment.
    // Restoring that behavior — when no map is available, inject
    // NOTHING. The AI behaves as it always has on cross-ref.
    var sectionIndexBlock = "";
    if (structuralMap && structuralMap.headerCount > 0) {
      // Section list — INCLUDES unnumbered headers (referenced by name
      // only, e.g. "the Confidentiality Section"). Indented by level so
      // the AI can see the hierarchy. Unnumbered headers are tagged
      // [unnumbered] so the AI knows there's no number to match — it
      // must match by title instead.
      var sectionListText = structuralMap.allSections().map(function (h) {
        var indent = "  ".repeat(Math.max(0, Math.min(h.level || 0, 6)));
        var prefixStr;
        var cleanNum = (h.number && h.number !== "[Unnumbered]") ? _cleanSectionNumber(h.number) : "";
        if (cleanNum) {
          prefixStr = cleanNum + " ";
        } else {
          prefixStr = "[unnumbered] ";
        }
        return indent + prefixStr + (h.title || "(no title)");
      }).join("\n");
      if (sectionListText) {
        // ─── OLD wording (2026-05-13 first iteration) ─────────────────
        // Kept as a comment so we can revert quickly if the new
        // emphatic version regresses anything:
        //
        //   "CROSS-REFERENCE RULE: For phrases like 'Section X.Y',
        //   'Article X', 'as set forth in Section X.Y', etc., check
        //   whether the cited number appears in SECTIONS above. If it
        //   does NOT, emit error_type 'Cross-Ref' with the cited phrase
        //   as exact_error and either (a) the nearest existing number
        //   as exact_fix when there's an obvious typo (digits
        //   transposed: 4.5 vs 5.4), or (b) the cited phrase unchanged
        //   as exact_fix with a 'no match' reason when truly dangling.
        //   Skip antecedent references like 'this Section' / 'the
        //   foregoing'."
        // ──────────────────────────────────────────────────────────────
        sectionIndexBlock =
          "\n\nSECTIONS IN THIS DOCUMENT (ground truth — these are the ONLY valid section anchors):\n" +
          sectionListText + "\n\n" +
          "CROSS-REFERENCE CHECK IS A TOP PRIORITY. Scan EVERY section reference in the document, not just obvious ones. This is mandatory — broken references are high-impact errors.\n\n" +
          "WHAT TO SCAN FOR (all of these patterns):\n" +
          "  • Numbered: 'Section X', 'Section X.Y', 'Section X.Y.Z', '§ X.Y', 'Sec. X.Y'\n" +
          "  • Article / Clause / Exhibit / Appendix variants: 'Article X', 'Article III', 'Clause 5', 'Exhibit A', 'Appendix 2'\n" +
          "  • Cited-by-name (unnumbered or compound): 'the Confidentiality Section', 'the Indemnification Article', 'the Termination clause'\n" +
          "  • Prepositional phrases: 'as set forth in / pursuant to / subject to / see / in accordance with / under / per Section X.Y'\n\n" +
          "VALIDATION:\n" +
          "  1. For NUMBERED references: cited number MUST appear verbatim in SECTIONS above.\n" +
          "  2. For NAMED references (unnumbered): the cited title MUST match a header title in SECTIONS above (case-insensitive substring match is OK — 'the Confidentiality Section' matches header '1 Confidentiality').\n" +
          "  3. If validation passes → silent pass (do NOT emit).\n" +
          "  4. If validation FAILS → MUST emit error_type 'Cross-Ref'. Every dangling reference MUST appear in your output — do not skip any.\n\n" +
          "OUTPUT FOR EACH FAILED VALIDATION:\n" +
          "  • exact_error = the cited phrase verbatim ('Section 4.5' or 'the Confidentiality Section')\n" +
          "  • exact_fix = the nearest existing number/title from SECTIONS when there is an obvious match (digit transposition: 4.5↔5.4; off-by-one: 5.3↔5.2; typo in name: 'Indemnification' vs 'Indemification'). If no near match exists, exact_fix = the cited phrase unchanged and reason should say 'no matching section in document.'\n" +
          "  • reason = brief explanation, e.g. 'References Section 4.5 which does not exist; nearest match is 5.4.'\n\n" +
          "SELF-REFERENCE CHECK (ALSO TOP PRIORITY): Each text entry has a `section` field naming the section it physically sits in. When a sentence cites its OWN section by number — 'this Section X', 'this Section X.Y', 'pursuant to this Section X', 'under this Article X' — the cited number MUST match the entry's `section` number. If it does NOT match → MUST emit error_type 'Cross-Ref'. exact_error = the cited phrase verbatim ('this Section 5'); exact_fix = the same phrase with the entry's actual section number ('this Section 3'); reason = e.g. 'Self-reference cites Section 5 but this text is in Section 3.' This is the most common drafting error from copy-pasted clauses — scan every 'this Section' / 'this Article' that carries a number.\n\n" +
          "SKIP ONLY antecedent references that DON'T cite any number: bare 'this Section', 'this Agreement', 'the foregoing', 'such Section', 'said Article'. A 'this Section' WITH a number is NOT skipped — it goes through the self-reference check above.";
      }
    }

    var thinkingBudgetMap = { Essential: 0, Balanced: 4096, Picky: 8192 };
    var thinkBudget = thinkingBudgetMap[sensitivity] != null
      ? thinkingBudgetMap[sensitivity] : 4096;

    var prompt = providers.ai.formatPrompt(promptRow.text, {
      instructionsBlock: instructions ? instructions + "\n" : "",
      sectionIndexBlock: sectionIndexBlock,
      text: payloadForAI,
    });
    // 2026-05-13: the CDN prompt template (data/prompts.json key
    // "errorCheck") doesn't have a `{{sectionIndexBlock}}` placeholder
    // — formatPrompt silently drops the substitution. When we have a
    // real SECTIONS list (only when the kernel exposed readStructuralMap
    // AND it found headers), splice it before the "Text to check:"
    // delimiter. When the block is empty (no map / no headers), splice
    // nothing — AI behaves exactly as v2 did on cross-ref.
    if (sectionIndexBlock && prompt.indexOf("SECTIONS IN THIS DOCUMENT") === -1) {
      var insertMarker = "Text to check:";
      var insertAt = prompt.indexOf(insertMarker);
      if (insertAt !== -1) {
        prompt = prompt.slice(0, insertAt) +
                 sectionIndexBlock + "\n\n" +
                 prompt.slice(insertAt);
      } else {
        prompt = prompt + "\n\n" + sectionIndexBlock;
      }
    }

    var rawData = await providers.ai.completeJSON(prompt, null, {
      thinkingBudget: thinkBudget,
      // Forward the cancel signal from init's overlay onCancel handler
      // so a Cancel-Request click aborts the actual fetch.
      signal: input && input.signal,
    });

    // v2-format compat (line 6299-6303).
    if (Array.isArray(rawData)) {
      rawData.forEach(function (r) {
        if (r.exact_error && !r.original) r.original = r.exact_error;
        if (r.exact_fix && !r.correction) r.correction = r.exact_fix;
        r.source = r.source || "ai";
      });
    }
    return _validateErrorData(rawData);
  })();

  // ── Step 4: Combine + sort ───────────────────────────────────────────
  var combined = await Promise.all([aiErrorsPromise, footerErrorsPromise]);
  var aiErrors = combined[0] || [];
  var footerErrors = combined[1] || [];
  var allErrors = footerErrors.concat(aiErrors);

  allErrors.sort(function (a, b) {
    var na = parseInt(((a.id || "").match(/\d+$/) || [0])[0]) || 0;
    var nb = parseInt(((b.id || "").match(/\d+$/) || [0])[0]) || 0;
    return na - nb;
  });

  // ── Step 5: Per-error bookmarks for precise Locate (v2 parity) ───────
  // FROM v2 _eliCreatePerErrorBookmarks (line 32936). For each error
  // whose id matches a paragraph bookmark, search the paragraph range
  // for `item.original` and drop a NEW bookmark `<paraId>_e<idx>` at
  // the exact match. Locate later uses `getBookmarkRangeOrNullObject`
  // on _errBookmark for direct jump (no body-wide search).
  // Each item gets:
  //   _errBookmark — name of the precise bookmark (or paragraph fallback)
  //   _precision   — "exact" | "paragraph" | "missing"
  //   _displayExcerpt — the trimmed window of paragraph text around the match
  await providers.host.runRaw("error_review:index", function (context) {
    if (!allErrors.length) return Promise.resolve();
    var ranges = allErrors.map(function (item) {
      if (!item || !item.id) return null;
      var r = context.document.getBookmarkRangeOrNullObject(item.id);
      r.load("text, isNullObject");
      return r;
    });
    return context.sync().then(async function () {
      for (var i = 0; i < allErrors.length; i++) {
        var item = allErrors[i];
        var pBkm = ranges[i];
        if (!item || !pBkm) continue;
        if (pBkm.isNullObject) {
          item._precision = "missing";
          continue;
        }
        var paraText = pBkm.text || "";
        item._displayExcerpt = providers.host.helpers.buildExcerpt(paraText, item.original, 3, 2);
        if (!item.original) {
          item._errBookmark = item.id;
          item._precision = "paragraph";
          continue;
        }
        var found = await providers.host.helpers.searchWithFallback(pBkm, item.original, context);
        var errBkmName = item.id + "_e" + i;
        if (found) {
          try { found.insertBookmark(errBkmName); } catch (e) { /* tolerate */ }
          item._errBookmark = errBkmName;
          item._precision = "exact";
        } else {
          item._errBookmark = item.id;
          item._precision = "paragraph";
        }
      }
      return context.sync();
    });
  }).catch(function () { /* tolerate — Locate falls back to body search */ });

  // ── Step 6: Enrich each error with section context from structural map ─
  // For each item, derive paragraph index from its `id` (e.g. "ELI_ER_47"
  // → 47) and look up the enclosing header. Adds:
  //   _sectionNumber   ("4.5" or "[Unnumbered]" for headers with no number)
  //   _sectionTitle    ("Confidentiality Period")
  //   _sectionAnchor   ("ELI_IDX_<headerIdx>") — for the section-tab
  //                                              click-to-jump behavior
  // Footer errors (id starts with "ELI_ER_footer_") have no paragraph
  // index and skip enrichment. Items with no resolvable section just
  // don't get the badge — view falls back to no-tab.
  //
  // 2026-05-13 fix: previously the anchor lookup used
  // `findHeaderByNumber(sec.number)` which returns null for
  // [Unnumbered] headers (kernel only indexes byNumber for real
  // numbers). Result: unnumbered section tabs rendered but click was a
  // silent no-op. Now we walk byParagraphIdx backward directly to find
  // the header row regardless of whether it has a number — that always
  // gives us the anchor.
  if (structuralMap && allErrors.length) {
    allErrors.forEach(function (item) {
      if (!item || !item.id) return;
      // Skip non-paragraph ids (footer errors, system errors).
      if (item.id.indexOf("_footer_") !== -1 || item.id.indexOf("_err") !== -1) return;
      var m = item.id.match(/_(\d+)$/);
      if (!m) return;
      var paraIdx = parseInt(m[1], 10);
      if (!isFinite(paraIdx)) return;
      var byParaIdx = structuralMap.byParagraphIdx || {};
      var sec = structuralMap.getSection(paraIdx);
      // Walk backward from this paragraph's idx to find the enclosing
      // header ROW so we can grab the anchor. Works for BOTH numbered
      // and unnumbered headers.
      var headRow = null;
      var thisRow = byParaIdx[paraIdx];
      if (thisRow && thisRow.isHeader) {
        headRow = thisRow;
      } else {
        for (var pj = paraIdx - 1; pj >= 0; pj--) {
          var c = byParaIdx[pj];
          if (c && c.isHeader) { headRow = c; break; }
        }
      }
      if (sec) {
        item._sectionNumber = _cleanSectionNumber(sec.number || "");
        item._sectionTitle = sec.title || "";
        if (headRow && headRow.anchor) item._sectionAnchor = headRow.anchor;
      } else {
        // 2026-05-13: no enclosing header found (paragraph sits BEFORE
        // any header in the doc — the preamble / "Document Introduction"
        // area). Use the kernel's `belongsTo` field so the card still
        // gets a context tab. byParagraphIdx[paraIdx].belongsTo defaults
        // to "Document Introduction" for body paragraphs that haven't
        // crossed a header yet (kernel readStructuralMap, line ~2110).
        var fallback = (thisRow && thisRow.belongsTo) || "Document Introduction";
        item._sectionNumber = "";          // no number → view will use unnumbered styling
        item._sectionTitle = fallback;
        item._sectionBelongsToOnly = true;  // hint to view: this is a belongsTo fallback,
                                            // not a real section header — render label
                                            // as "§ <fallback>" and skip the section-jump
                                            // click target (no header to jump to).
      }
    });
  }

  onLog({
    kind: "step", id: "done", icon: allErrors.length === 0 ? "✅" : "🔍",
    text: allErrors.length === 0
      ? "No errors found"
      : allErrors.length + " error(s) detected",
  });

  var totalWords = (extracted.fullText || "")
    .split(/\s+/)
    .filter(function (w) { return w.length > 0; }).length;

  return _buildResult(allErrors, [], totalWords, settings, input,
    allErrors.length === 0
      ? "Document passed all checks."
      : allErrors.length + " issue(s) detected (" +
        aiErrors.length + " from AI, " + footerErrors.length + " footer)."
  );
}

view.renderSettingsDialog:
function renderSettingsDialog(opts) {
  function _sensCard(value, badge, desc, checked) {
    return '<label class="_eli3_er_sens_card' + (checked ? " _eli3_er_sens_card_active" : "") + '">' +
      '<input type="radio" name="_eli3_er_sens" value="' + value + '"' +
        (checked ? " checked" : "") + ' class="_eli3_er_sens_input">' +
      '<div class="_eli3_er_sens_head">' +
        '<span class="_eli3_er_sens_name">' + value + '</span>' +
        '<span class="_eli3_er_sens_badge">' + badge + '</span>' +
      '</div>' +
      '<div class="_eli3_er_sens_desc">' + desc + '</div>' +
    '</label>';
  }
  opts = opts || {};
  var savedSensitivity = opts.sensitivity || "Balanced";
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return Promise.resolve(null);
  return new Promise(function (resolve) {
    // Defensive overlay sweep — see renderReportDialog comment.
    try {
      document.querySelectorAll(
        "._eli3_ds_progress, ._eli3_er_progress, #_eli3_er_progress, #_eli3_ds_progress, #loading"
      ).forEach(function (n) { if (n.parentNode) n.parentNode.removeChild(n); });
    } catch (e) { /* tolerate */ }
    mount.innerHTML = "";
    var panel = document.createElement("div");
    // `tool--error_review` is the scope hook style.css uses to wipe
    // the inherited docuscrub cyan left-bar (see notes in style.css).
    panel.className = "_eli3_ds_panel tool--error_review";
    panel.style.cssText =
      "display:flex;flex-direction:column;width:100%;height:100%;background:#fff;overflow:hidden;box-sizing:border-box";
    panel.innerHTML =
      '<div class="_eli3_ds_header">' +
        '<div class="_eli3_ds_header_eyebrow">PROOFREAD</div>' +
        '<div class="_eli3_ds_header_title"><span>🔍</span> Error Review · Settings</div>' +
      '</div>' +
      '<div class="_eli3_ds_body">' +
        '<p class="_eli3_ds_intro">Choose how aggressive the AI should be. Saves apply to future scans.</p>' +
        '<div class="_eli3_ds_eyebrow_blue">🎚️ Sensitivity</div>' +
        '<div class="_eli3_er_sens_grid">' +
          _sensCard("Essential", "Fast",
            "Periods, double spaces, obvious typos. ~30s.",
            savedSensitivity === "Essential") +
          _sensCard("Balanced", "Default",
            "Adds grammar + US spelling enforcement. ~60s.",
            savedSensitivity === "Balanced") +
          _sensCard("Picky", "Strict",
            "Adds undefined-capitalized-term scan. ~90s.",
            savedSensitivity === "Picky") +
        '</div>' +
        '<div class="_eli3_ds_run_row">' +
          '<button id="_eli3_er_cancel" class="_eli3_er_btn _eli3_er_btn_secondary" style="border-radius:0">Cancel</button>' +
          '<button id="_eli3_er_save" class="_eli3_er_btn _eli3_er_btn_primary" style="border-radius:0">Save</button>' +
        '</div>' +
      '</div>';
    mount.appendChild(panel);
    function _selected() {
      var picked = panel.querySelector('input[name="_eli3_er_sens"]:checked');
      return picked ? picked.value : "Balanced";
    }
    panel.querySelector("#_eli3_er_cancel").onclick = function () { resolve(null); };
    panel.querySelector("#_eli3_er_save").onclick = function () { resolve({ sensitivity: _selected() }); };
    Array.prototype.forEach.call(
      panel.querySelectorAll("._eli3_er_sens_card"),
      function (card) {
        card.addEventListener("click", function () {
          Array.prototype.forEach.call(
            panel.querySelectorAll("._eli3_er_sens_card"),
            function (c) { c.classList.remove("_eli3_er_sens_card_active"); }
          );
          card.classList.add("_eli3_er_sens_card_active");
        });
      }
    );
  });
}

// ── Progress overlay ─────────────────────────────────────────────────
// Fully opaque overlay (you can't see anything behind it). Defensively
// hides the v2 carry-over #loading element. Robot loader + a single
// "Scanning…" caption + a CANCEL REQUEST button (matches v2 line 13206+).
// Cancel triggers the cancel callback if provided; tool's analyze
// promise will reject and clean up. Returns { close, log, onCancel }.

view.renderProgressOverlay:
function renderProgressOverlay(cb) {
  // Hide the v2 #loading element if a previous run left it visible.
  try {
    var v2Loading = document.getElementById("loading");
    if (v2Loading) v2Loading.classList.add("hidden");
  } catch (e) { /* tolerate */ }

  var onCancel = (cb && typeof cb.onCancel === "function") ? cb.onCancel : null;

  // Single overlay for the entire scan (extract → footer → AI → done).
  // Styling lives in taskpane_v3.css §17 (unlayered, so it beats both
  // legacy and components rules regardless of paste order).
  var ov = document.createElement("div");
  ov.id = "_eli3_er_progress";
  ov.className = "_eli3_er_progress_overlay";
  // 2026-05-26: replaced the robot-teeth-brushing animation with a
  // large ELI mascot brushing his teeth. Same conceit (mascot scans
  // the doc → cleans up errors → polished result) but on-brand
  // instead of a generic robot. Mascot SVG comes from
  // eli.ui.mascot() (published by eli_mascot_studio at preload).
  // Fallback to the old robot if the helper isn't loaded yet.
  var mascotSvg = (window.eli && window.eli.ui && window.eli.ui.mascot)
    ? window.eli.ui.mascot()
    : null;
  var loaderInner;
  if (mascotSvg) {
    // 2026-05-26: mouth overlay (open mouth + 5 white teeth) sits ON
    // TOP of the mascot SVG to cover the closed-smile arc. Inline SVG
    // so the rounded rects + pink mouth backdrop scale crisply at any
    // size. Brush trail is small (±6px) so it visibly stays on the
    // teeth instead of swinging past the cheeks.
    // 2026-05-26 v3: teeth injected INSIDE the mascot SVG (replacing
    // the closed-smile path) so they're part of the _eli3_ems_head
    // group that's already animated by the studio's head_bob keyframes.
    // No pixel-math + no sync issues — teeth literally ARE the head.
    // Brush + foam stay as DOM overlays (emoji can't go in SVG cleanly)
    // but live inside _eli3_er_face_overlay which bobs in lockstep with
    // the same timing. Coordinates in viewBox space (0-120) — mouth
    // sits at y=80, 16 wide × 6 tall, with 4 white teeth inside.
    var teethSvg =
      '<rect x="52" y="79" width="16" height="7" rx="2.2" fill="#7c1d1d"/>' +
      '<rect x="53.4" y="80.4" width="2.8" height="4.5" rx="0.5" fill="#fff"/>' +
      '<rect x="56.8" y="80.4" width="2.8" height="4.5" rx="0.5" fill="#fff"/>' +
      '<rect x="60.2" y="80.4" width="2.8" height="4.5" rx="0.5" fill="#fff"/>' +
      '<rect x="63.6" y="80.4" width="2.8" height="4.5" rx="0.5" fill="#fff"/>';
    // Replace the closed-smile arc with the open-mouth+teeth block.
    // The smile path is rendered just before any facial hair fragment;
    // replacing here preserves z-order (facial hair still renders on top).
    mascotSvg = mascotSvg.replace(
      '<path d="M55,81 Q60,85 65,81" stroke="#a04040" stroke-width="1.5" fill="none" stroke-linecap="round"/>',
      teethSvg
    );
    loaderInner =
      '<div class="_eli3_er_mascot_loader">' +
        '<div class="_eli3_er_mascot_avatar">' + mascotSvg + '</div>' +
        '<div class="_eli3_er_face_overlay" aria-hidden="true">' +
          '<div class="_eli3_er_brush">🪥</div>' +
          '<div class="_eli3_er_foam f1"></div>' +
          '<div class="_eli3_er_foam f2"></div>' +
          '<div class="_eli3_er_foam f3"></div>' +
        '</div>' +
      '</div>';
  } else {
    // Fallback to v2 robot-teeth — same DOM as before.
    loaderInner =
      '<div class="robot-head">' +
        '<div class="robot-eyes">' +
          '<div class="robot-eye"></div><div class="robot-eye"></div>' +
        '</div>' +
        '<div class="mouth-container">' +
          '<div class="teeth-row upper">' +
            '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
            '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
            '<div class="tooth"></div>' +
          '</div>' +
          '<div class="teeth-row lower">' +
            '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
            '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
            '<div class="tooth"></div>' +
          '</div>' +
          '<div class="brush-anim">🪥</div>' +
          '<div class="foam f1"></div><div class="foam f2"></div><div class="foam f3"></div>' +
        '</div>' +
      '</div>';
  }
  ov.innerHTML =
    '<div class="_eli3_er_progress_panel">' +
      '<div class="loading-card robot-loader" style="background:transparent;border:none;box-shadow:none;padding:10px 0;">' +
        loaderInner +
        '<p class="_eli3_er_progress_msg">Scanning…</p>' +
      '</div>' +
      '<button id="_eli3_er_cancel_request" type="button" class="_eli3_er_cancel_btn">' +
        'CANCEL REQUEST' +
      '</button>' +
    '</div>';

  document.body.appendChild(ov);

  var cancelBtn = ov.querySelector("#_eli3_er_cancel_request");
  if (cancelBtn) {
    cancelBtn.onclick = function () {
      cancelBtn.disabled = true;
      cancelBtn.textContent = "Cancelling…";
      if (typeof onCancel === "function") {
        try { onCancel(); } catch (e) { /* tolerate */ }
      }
    };
  }

  function log(entry) {
    if (!entry || !entry.text) return;
    var p = ov.querySelector("._eli3_er_progress_msg");
    if (p) p.textContent = entry.text;
  }
  function close() {
    if (ov.parentNode) ov.parentNode.removeChild(ov);
  }
  return { close: close, log: log };
}

