  }
  function _bodySearchReplace(context, phrase, fix) {
    // Last resort — bookmark missing AND in-paragraph search failed.
    // Body-wide search using the locate-fallback cascade (string-strip
    // variants distinct from the kernel's wildcard cascade — kept for
    // forgiving recovery from missing bookmarks).
    var variants = _searchVariants(phrase);
    var searches = variants.map(function (v) {
      return _trySearchInRange(context.document.body, v);
    });
    return context.sync().then(function () {
      for (var i = 0; i < searches.length; i++) {
        if (searches[i].items.length > 0) {
          return eli.host.helpers.applyMinimalEdit(searches[i].items[0], phrase, fix, context)
            .then(function () { return context.sync(); });
        }
      }
      var ToolErr3 = window.eli && window.eli.errors && window.eli.errors.ToolError || Error;
      throw new ToolErr3("Couldn't find '" + phrase + "' in document.");
    });
  }
  // Footer replace — sibling of _bodySearchReplace for footer errors.
  // Parses the targeted (section, footer-type) from the item id; if
  // parsable, replaces inside that specific footer first. Otherwise
  // (or on a miss) scans every section × footer type. Replaces with
  // a direct range.search → applyMinimalEdit so font/format on the
  // surrounding chars is preserved (same behavior as body replace).
  function _footerReplace(context, item, phrase, fix) {
    var ToolErr = (window.eli && window.eli.errors && window.eli.errors.ToolError) || Error;
    if (!phrase) throw new ToolErr("Empty 'original' — can't replace.");
    var targetSectionIdx = -1;
    var targetType = "";
    if (item && item.id) {
      var m = String(item.id).match(/footer_(\d+)_([A-Za-z]+)/);
      if (m) {
        targetSectionIdx = parseInt(m[1], 10) - 1;
        targetType = m[2];
      }
    }
    var sections = context.document.sections;
    sections.load("items");
    return context.sync().then(function () {
      function _tryReplaceInFooter(sec, ftype) {
        if (!sec) return Promise.resolve(false);
        var footer;
        try {
          footer = sec.getFooter ? sec.getFooter(ftype) : sec.footers.getItem(ftype);
        } catch (e) { return Promise.resolve(false); }
        if (!footer) return Promise.resolve(false);
        var fr = footer.getRange();
        var sr = fr.search(phrase, { matchCase: false, ignorePunct: true, ignoreSpace: true });
        sr.load("items");
        return context.sync().then(function () {
          if (!sr.items || !sr.items.length) return false;
          return eli.host.helpers.applyMinimalEdit(sr.items[0], phrase, fix, context)
            .then(function () { return context.sync(); })
            .then(function () { return true; });
        });
      }
      // Path 1: explicit target.
      if (targetSectionIdx >= 0 && targetSectionIdx < sections.items.length && targetType) {
        return _tryReplaceInFooter(sections.items[targetSectionIdx], targetType).then(function (ok) {
          if (ok) return true;
          return _scanReplace();
        });
      }
      return _scanReplace();

      function _scanReplace() {
        var types = ["Primary", "FirstPage", "EvenPages"];
        var i = 0, j = 0;
        function _step() {
          if (i >= sections.items.length) {
            throw new ToolErr("Couldn't find '" + phrase + "' in any footer.");
          }
          if (j >= types.length) { i++; j = 0; return _step(); }
          return _tryReplaceInFooter(sections.items[i], types[j++]).then(function (ok) {
            if (ok) return true;
            return _step();
          });
        }
        return _step();
      }
    });
  }

  // ── Scan flow ────────────────────────────────────────────────────────
  function _runScan(settings) {
    var mount = document.getElementById("_eli3_dashboard_root");

    function _safeTransition(target) {
      try { eli.fsm.transition(target); }
      catch (e) { /* tolerate */ }
    }
    function _goHome() {
      if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
      else if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
    }

    _safeTransition("scanning");
    // Cancel token threaded into eli.ai so a user-clicked cancel button
    // aborts the in-flight AI request rather than just dismissing UI.
    var cancelToken = (eli.cancel && typeof eli.cancel.token === "function")
      ? eli.cancel.token()
      : null;
    var overlay = renderProgressOverlay({
      onCancel: function () {
        // Abort the AI request mid-flight. The analyze().catch handler
        // below tears down the overlay + transitions back to idle.
        if (cancelToken && typeof cancelToken.abort === "function") {
          try { cancelToken.abort(); } catch (e) { /* tolerate */ }
        }
      },
    });
    var providers = { host: eli.host, ai: eli.ai, storage: eli.storage };
    var input = {
      settings: settings,
      onLog: overlay.log,
      docHash: null,
      // Engine forwards this signal into eli.ai.completeJSON's opts.signal.
      signal: cancelToken && cancelToken.signal,
    };

    function _afterAnalyze(result) {
      try {
        if (eli.stats) {
          // 2026-05-18 v48: appOpenedError MOVED to tile-handler entry
          // below. Keep workflow stats (docsReviewed, errorsScanned,
          // errorsFound) here — those measure scan output, not launch.
          eli.stats.record("docsReviewed");
          eli.stats.record("errorsScanned");
          if (result.items && result.items.length) {
            eli.stats.record("errorsFound", result.items.length);
          }
        }
        // Event-based trophies: Needle in a Haystack (t106), Flawless
        // Victory (t107). Both predicate on word count + error count.
        // Engine returns totalWords directly on the result.
        try {
          if (eli.trophies && typeof eli.trophies.evaluate === "function") {
            eli.trophies.evaluate("error_scan_complete", {
              totalErrors: (result.items || []).length,
              wordCount: Number(result && result.totalWords) || 0,
            });
          }
        } catch (_) {}
        if (eli.activity) {
          var summary = result.items.length === 0
            ? "✅ No errors found"
            : result.items.length + " issue(s) detected";
          // Store the full result so the session-feed click handler can
          // restore the report later. Strip wrongness-style raw doc text
          // since result already only contains AI-derived data; nothing
          // sensitive to redact here.
          eli.activity.add({
            type: "error_review",
            icon: "🔍",
            label: "Error Review",
            summary: summary,
            payload: result,
            // Tells the kernel feed-click handler which channel/key to
            // dispatch. Tool registers an activity_restore handler below.
            restoreChannel: "activity_restore",
            restoreKey: "error_review",
          });
        }
        if (eli.wrongness) eli.wrongness.capture("error_review", input, result, {});
      } catch (sideErr) {
        eli.log.event("tool", "error_review_side_effects_failed", {
          error: sideErr && sideErr.message,
        });
      }
      _safeTransition("rendering");
      renderReportDialog({
        result: result,
        mount: mount,
        onLocate: _locate,
        onAcceptOne: _acceptOne,
        onClose: function () {
          _safeTransition("idle");
          _goHome();
        },
      });
    }

    analyze(input, providers).then(function (result) {
      overlay.close();
      try {
        _afterAnalyze(result);
      } catch (renderErr) {
        eli.log.event("tool", "error_review_render_failed", {
          error: renderErr && renderErr.message,
          stack: (renderErr && renderErr.stack || "").slice(0, 500),
        });
        if (typeof showToast === "function") {
          showToast("Report render failed: " + (renderErr && renderErr.message || "unknown"), "err");
        }
        _goHome();
        _safeTransition("error");
        setTimeout(function () { try { eli.fsm.transition("idle"); } catch (e) {} }, 100);
      }
    }).catch(function (err) {
      overlay.close();
      _goHome();
      // 2026-05-16: distinguish user-cancel from real failure. cancelToken
      // abort produces an AbortError / message containing "abort"/"cancel"
      // — route those through showCancelledState (eli_kit's cancelled
      // screen subscribes to the resulting FSM transition). Real failures
      // continue to the error state + toast.
      var msg = (err && err.message) || "";
      var isCancel = /abort|cancel/i.test(msg);
      if (isCancel) {
        eli.log.event("tool", "error_review_cancelled", { msg: msg });
        if (typeof showCancelledState === "function") {
          try { showCancelledState(); } catch (_) {}
        } else {
          _safeTransition("idle");
        }
        return;
      }
      _safeTransition("error");
      if (typeof showToast === "function") {
        showToast("Scan failed: " + (msg || "unknown"), "err");
      }
      eli.log.event("tool", "error_review_failed", { error: msg });
      setTimeout(function () { try { eli.fsm.transition("idle"); } catch (e) {} }, 100);
    });
  }

  // ── Tile handler (main click) ────────────────────────────────────────
  // Direct path: API-key check → redlines warn → scope detect → scan.
  // No settings dialog. Settings live behind the gear icon.
  function tileHandler() {
    if (!eli.ai || !eli.ai.hasApiKey()) {
      if (typeof showToast === "function") {
        showToast("Set a Gemini API key in Settings → Global first.", "warn");
      }
      // Open settings as a courtesy so the user can fix it.
      if (eli.settings && eli.settings.show) eli.settings.show();
      return;
    }
    // 2026-05-18 v48: record launch HERE (after the key check, so a
    // missing-API-key bounce isn't counted) instead of in _afterAnalyze
    // — that way cancel-before-scan still counts as a launch, and
    // re-scans within the same launch don't double-record.
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedError"); } catch (e) {}

    var saved = _readUserSettings();
    var sensitivity = saved.sensitivity || "Balanced";

    // Pre-scan: redlines warning, then selection-scope decision.
    _checkRedlines().then(function (proceed) {
      if (!proceed) return;
      _detectScope().then(function (initial) {
        if (initial === "askUser") {
          _askScope().then(function (scope) {
            if (!scope) return; // user cancelled
            _runScan({ sensitivity: sensitivity, scope: scope });
          });
        } else {
          _runScan({ sensitivity: sensitivity, scope: "full" });
        }
      });
    });
  }

  // ── Gear handler (settings) ──────────────────────────────────────────
  // Opens the sensitivity picker. Settings persist on Save (closing the
  // dialog with Save). Cancel just dismisses.
  function gearHandler() {
    var saved = _readUserSettings();
    var hasApiKey = !!(eli.ai && eli.ai.hasApiKey());
    var mount = document.getElementById("_eli3_dashboard_root");
    renderSettingsDialog({
      hasApiKey: hasApiKey,
      sensitivity: saved.sensitivity || "Balanced",
      mount: mount,
      gearMode: true, // tells the view to render Save/Cancel instead of Scan/Home
    }).then(function (settings) {
      if (settings) {
        var s = _readUserSettings();
        s.sensitivity = settings.sensitivity;
        _writeUserSettings(s);
        if (typeof showToast === "function") {
          showToast("Saved: sensitivity " + settings.sensitivity, "ok");
        }
      }
      if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
    });
  }

  // Register all three channels:
  //   tile             — main click runs scan
  //   tile_settings    — gear icon opens sensitivity picker
  //   activity_restore — feed-item click re-renders the saved report
  eli.register({
    tile: { "app_error_review": tileHandler },
    tile_settings: { "app_error_review": gearHandler },
    activity_restore: {
      "error_review": function (payload) {
        var mount = document.getElementById("_eli3_dashboard_root");
        if (!mount || !payload) return;
        // Re-show the report panel using the saved result. FSM goes to
        // rendering on entry; idle on close (same as a fresh scan).
        try { eli.fsm.transition("rendering"); } catch (e) { /* tolerate */ }
        renderReportDialog({
          result: payload,
          mount: mount,
          onLocate: _locate,
          onAcceptOne: _acceptOne,
          onClose: function () {
            try { eli.fsm.transition("idle"); } catch (e) { /* tolerate */ }
            if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
          },
        });
      },
    },
  });
  eli.log.event("tool", "error_review_initialized", {});
}

jsonTools.css:
/* error_review tool styles. Injected by kernel as <style data-tool="error_review">. */

/* Both error_review panels (settings dialog + results report) reuse
 * docuscrub's `_eli3_ds_panel` class for layout — but docuscrub
 * stamps a 5px cyan `border-left: 5px solid #00acc1` on every panel
 * with that class. That's docuscrub's identity color (hygiene), not
 * error_review's (proofread). Strip it everywhere this tool owns.
 * Selector specificity (0,2,0) beats docuscrub's (0,1,0). */
.tool--error_review ._eli3_ds_panel,
._eli3_ds_panel.tool--error_review {
  border-left: none;
  border: 1px solid #d1d5db;
}

._eli3_er_progress_overlay {
  position: fixed; inset: 0; z-index: 9999;
  display: flex; align-items: center; justify-content: center;
  background: rgba(15, 23, 42, 0.55);
  backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px);
  animation: _eli3_loading_fade .25s ease;
}
._eli3_er_progress_panel {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 22px; padding: 32px;
}
._eli3_er_progress_msg {
  margin: 18px 0 0;
  font: 700 12px/1.4 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 1.5px;
  color: #fff; text-shadow: 0 1px 4px rgba(0,0,0,0.6);
  text-align: center;
  animation: _eli3_loading_pulse 2s infinite ease-in-out;
}
._eli3_er_cancel_btn {
  padding: 8px 22px;
  font: 700 11px/1 'Inter', sans-serif;
  letter-spacing: 0.5px; text-transform: uppercase; color: #fff;
  background: linear-gradient(to bottom, rgba(255,255,255,0.18) 0%, rgba(255,255,255,0.08) 100%);
  border: 1px solid rgba(255,255,255,0.3);
  cursor: pointer; transition: all .2s ease;
}
._eli3_er_cancel_btn:hover {
  background: linear-gradient(to bottom, rgba(255,255,255,0.28) 0%, rgba(255,255,255,0.14) 100%);
  border-color: rgba(255,255,255,0.5);
}
._eli3_er_cancel_btn:disabled { opacity: 0.6; cursor: not-allowed; }

/* Cancel button on the tool-owned smile-overlays (legal_risks + compare,
   2026-05-16). Translucent platinum on the dark backdrop, gold border on
   hover. Lives here because the rest of the loader chrome (.robot-loader,
   ._eli3_er_progress_overlay, ._eli3_er_progress_panel) lives in this
   bundle too — both tools call eli.tools.ensureLoaded("error_review")
   before painting their overlay, so the CSS is always present. Centered
   horizontally under the loading message via display:block + auto margins
   (the parent .loading-card has no centering rules of its own). */
._eli3_loading_cancel {
  display: block;
  margin: 14px auto 0;
  padding: 7px 22px;
  background: linear-gradient(to bottom, rgba(255, 255, 255, 0.18) 0%, rgba(255, 255, 255, 0.08) 100%);
  border: 1px solid rgba(255, 255, 255, 0.35);
  border-radius: 4px;
  color: #ffffff;
  font: 700 11px/1 'Inter', sans-serif;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  cursor: pointer;
  transition: all .15s ease;
}
._eli3_loading_cancel:hover {
  background: linear-gradient(to bottom, rgba(255, 255, 255, 0.3) 0%, rgba(255, 255, 255, 0.16) 100%);
  border-color: rgba(201, 162, 39, 0.6);
  color: #fdf3c4;
}
._eli3_loading_cancel:active {
  transform: translateY(1px);
}

/* Settings dialog — sensitivity choice cards (Essential / Balanced / Picky).
   Stacked boxes with title + badge in head, description below. Active card
   gets a blue accent border + light-blue tint to confirm selection. */
._eli3_er_sens_grid {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 6px 0 14px;
}
._eli3_er_sens_card {
  display: block;
  padding: 12px 14px;
  background: #fff;
  border: 1px solid #cbd5e1;
  border-left: 4px solid #cbd5e1;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s, box-shadow 0.15s;
}
._eli3_er_sens_card:hover {
  border-color: #93c5fd;
  border-left-color: #93c5fd;
  background: #f8fafc;
}
._eli3_er_sens_card_active {
  border-color: #1565c0;
  border-left-color: #1565c0;
  background: linear-gradient(180deg, #f0f7ff 0%, #e3f2fd 100%);
  box-shadow: 0 2px 6px rgba(21, 101, 192, 0.15);
}
._eli3_er_sens_input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}
._eli3_er_sens_head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 4px;
}
._eli3_er_sens_name {
  flex: 1;
  font: 700 13px/1.2 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_er_sens_card_active ._eli3_er_sens_name { color: #0d47a1; }
._eli3_er_sens_badge {
  flex: 0 0 auto;
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #475569;
  background: #f1f5f9;
  border: 1px solid #cbd5e1;
  padding: 3px 7px;
  border-radius: 10px;
}
._eli3_er_sens_card_active ._eli3_er_sens_badge {
  color: #fff;
  background: #1565c0;
  border-color: #0d47a1;
}
._eli3_er_sens_desc {
  font: 500 11px/1.4 'Inter', sans-serif;
  color: #64748b;
}
._eli3_er_sens_card_active ._eli3_er_sens_desc { color: #1e293b; }

/* Settings dialog — primary/secondary buttons in the run-row. Match the
   platinum (gray neutral) + royal-blue (primary) convention used across
   the kernel + other tools. */
._eli3_er_btn {
  padding: 9px 18px;
  font: 700 11px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  cursor: pointer;
  transition: all 0.15s ease;
  border-radius: 0;
}
._eli3_er_btn_primary {
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid #0d47a1;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
}
._eli3_er_btn_primary:hover {
  transform: translateY(-1px);
  box-shadow: 0 3px 8px rgba(21, 101, 192, 0.3);
}
._eli3_er_btn_secondary {
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  color: #546e7a;
  border: 1px solid #b0bec5;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.8);
  box-shadow: inset 0 1px 0 #ffffff, 0 1px 2px rgba(0, 0, 0, 0.08);
}
._eli3_er_btn_secondary:hover {
  background: linear-gradient(to bottom, #fff 0%, #e3f2fd 100%);
  color: #1565c0;
  border-color: #90caf9;
}

/* Settings dialog sensitivity badges (Fast / Default / Strict) hide
 * before names at narrow widths. Names always stay. */
@media (max-width: 380px) {
  ._eli3_er_sens_badge { display: none; }
}


/* ─── Robot loader (moved from taskpane_v3.css 3067-3212 in Batch 5C 2026-05-11) ───
 * Full v2-port robot scrubber animation. error_review is the only consumer
 * (rendered inside ._eli3_er_progress_panel by view.js). All !important
 * markers on border-radius are needed to win over the kernel reset rule. */
/* Robot loader (full v2-port) — copied from taskpane.css:1236-1431 so v3
 * owns the loader CSS end-to-end. Unlayered so it beats the global
 * `* { border-radius: 0 !important }` reset on intentional shapes. All
 * !important markers on border-radius are needed to win over that reset. */
.robot-loader .robot-head {
  width: 140px;
  background: linear-gradient(145deg, #eceff1, #ffffff);
  border: 3px solid #b0bec5;
  border-radius: 25px 25px 12px 12px !important;
  padding: 20px 15px 5px 15px;
  box-shadow:
    inset -3px -3px 8px rgba(0, 0, 0, 0.05),
    inset 3px 3px 8px rgba(255, 255, 255, 1),
    0 10px 25px rgba(0, 0, 0, 0.2),
    0 4px 6px rgba(0, 0, 0, 0.1);
  position: relative;
  border-bottom: 6px solid #cfd8dc;
  margin: 0 auto;
}
.robot-loader .robot-head::before {
  content: '';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  width: 25px;
  height: 12px;
  background: #b0bec5;
  border-radius: 6px 6px 0 0 !important;
  border: 2px solid #90a4ae;
  border-bottom: none;
}
.robot-loader .robot-head::after {
  content: '';
  position: absolute;
  top: -22px;
  left: 50%;
  transform: translateX(-50%);
  width: 10px;
  height: 10px;
  background: #ff5252;
  border-radius: 50% !important;
  box-shadow: 0 0 10px #ff5252;
  animation: blinkAntenna 1s infinite alternate;
}
@keyframes blinkAntenna {
  0%, 100% { opacity: 1; box-shadow: 0 0 12px #ff5252; }
  50%      { opacity: 0.3; box-shadow: 0 0 4px #ff5252; }
}

.robot-loader .robot-eyes {
  display: flex;
  justify-content: space-evenly;
  padding: 0 15px;
  margin-bottom: 15px;
}
.robot-loader .robot-eye {
  width: 16px;
  height: 24px;
  background: #4fc3f7;
  border-radius: 10px !important;
  box-shadow: 0 0 10px #4fc3f7, inset 0 0 5px #fff;
  animation: friendlyBlink 3.5s infinite;
}
@keyframes friendlyBlink {
  0%, 92%, 100% { transform: scaleY(1); }
  96%           { transform: scaleY(0.1); }
}

.robot-loader .mouth-container {
  position: relative;
  width: 100px;
  height: 34px;
  background: #8a0000;
  border: 3px solid #c41230;
  border-radius: 2px 2px 50px 50px !important;
  box-shadow:
    inset 0 0 8px rgb(0 0 0 / 0.5),
    0 4px 10px rgb(0 0 0 / 0.2);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  overflow: hidden;
  margin: 0 auto 15px auto;
}

.robot-loader .teeth-row {
  display: flex;
  gap: 0;
  padding: 0 8px;
}
.robot-loader .teeth-row.upper .tooth {
  border-radius: 0 0 4px 4px !important;
  border-top: none;
}
.robot-loader .teeth-row.lower .tooth {
  border-radius: 4px 4px 0 0 !important;
  border-bottom: none;
}
.robot-loader .tooth {
  width: 10px;
  height: 11px;
  background: #fff;
  border: 1px solid #cfd8dc;
  flex-shrink: 0;
  border-radius: 1px !important;
}

.robot-loader .brush-anim {
  position: absolute;
  top: 50%;
  left: 50%;
  font-size: 26px;
  z-index: 10;
  animation: scrubWide 0.5s infinite ease-in-out alternate;
  transform-origin: center center;
  margin-top: -13px;
  margin-left: -13px;
}
@keyframes scrubWide {
  0%   { transform: translateX(-25px) translateY(-3px) rotate(-10deg); }
  100% { transform: translateX(25px)  translateY(-3px) rotate(10deg); }
}

.robot-loader .foam {
  position: absolute;
  width: 10px;
  height: 10px;
  background: #fff;
  border-radius: 50% !important;
  opacity: 0;
  z-index: 15;
  box-shadow: 0 0 5px 1px rgb(255 255 255 / 0.8);
  animation: foamPopSmall 1.2s infinite ease-out;
  left: 50%;
  margin-left: -5px;
}
.robot-loader .f1 { top: 12px; animation-delay: 0s; }
.robot-loader .f2 { top: 10px; animation-delay: 0.4s; }
.robot-loader .f3 { top: 14px; animation-delay: 0.8s; }
@keyframes foamPopSmall {
  0%   { transform: scale(0)   translateY(0);   opacity: 0; }
  30%  {                                        opacity: 0.9; }
  100% { transform: scale(1.8) translateY(-20px); opacity: 0; }
}

/* ── ELI mascot brushing-teeth loader ──────────────────────────────────
   2026-05-26 v3: SQUARE wrapper (300×300) so the SVG fills it exactly
   (no preserveAspectRatio offset that broke v2's pixel math). Teeth
   are now injected INSIDE the mascot SVG (replacing the smile path)
   so they bob automatically with the head group — no sync needed.
   Brush + foam stay as DOM overlays inside _eli3_er_face_overlay,
   which bobs with the same 1.8s alternate timing as the head group.

   Geometry at 300×300 (scale = 300/120 = 2.5):
     mouth center viewBox (60, 82.5) → pixel (150, 206)
     brush top ≈ 195 (bristles around y=205) */
._eli3_er_mascot_loader {
  position: relative;
  width: 300px;
  height: 300px;
  margin: 0 auto 12px;
}
._eli3_er_mascot_avatar {
  width: 100%;
  height: 100%;
  filter: drop-shadow(0 6px 14px rgba(13, 71, 161, 0.32))
          drop-shadow(0 2px 3px rgba(0, 0, 0, 0.18));
}
._eli3_er_mascot_avatar svg {
  width: 100%;
  height: 100%;
  display: block;
}
/* face_overlay — bobs in lockstep with the mascot's head group. */
._eli3_er_face_overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
  animation: _eli3_er_face_bob 1.8s ease-in-out infinite alternate;
}
@keyframes _eli3_er_face_bob {
  0%   { transform: translateY(0); }
  100% { transform: translateY(-2px); }
}
/* Brush — smaller (26px font) + tighter ±6px travel so it stays on
   the teeth instead of swinging past the cheeks. Positioned so the
   bristle tip rests just above the teeth (viewBox y=80 → 200px). */
._eli3_er_brush {
  position: absolute;
  font-size: 26px;
  top: 192px;
  left: 50%;
  margin-left: -13px;
  animation: _eli3_er_brush_move 0.55s ease-in-out infinite alternate;
  transform-origin: center 80%;
  z-index: 2;
  filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.25));
}
@keyframes _eli3_er_brush_move {
  0%   { transform: translateX(-6px) rotate(-12deg); }
  100% { transform: translateX(6px)  rotate(12deg); }
}
._eli3_er_foam {
  position: absolute;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.96);
  border: 1px solid #cbd5e1;
  opacity: 0;
  z-index: 3;
  box-shadow: 0 0 4px rgba(255, 255, 255, 0.7);
}
._eli3_er_foam.f1 {
  top: 218px; left: 46%;
  animation: _eli3_er_foam_pop 1.4s ease-out 0s   infinite;
}
._eli3_er_foam.f2 {
  top: 228px; left: 56%;
  animation: _eli3_er_foam_pop 1.4s ease-out 0.45s infinite;
}
._eli3_er_foam.f3 {
  top: 222px; left: 40%;
  animation: _eli3_er_foam_pop 1.4s ease-out 0.9s  infinite;
}
@keyframes _eli3_er_foam_pop {
  0%   { opacity: 0; transform: scale(0.4) translateY(0); }
  35%  { opacity: 1; transform: scale(1)   translateY(-3px); }
  100% { opacity: 0; transform: scale(0.6) translateY(-20px); }
}
